import { Router } from "express";
import { type ProductRepository } from "../models/Product.ts";

export function productsRouter(repository: ProductRepository): Router {
  const router = Router();

  // implements get-products GET /products
  // auth: Shopper
  router.get("/", async (req, res) => {
    res.json(await repository.list());
  });

  // implements get-products-id GET /products/{id}
  // auth: unauthenticated
  router.get("/:id", async (req, res) => {
    const found = await repository.get(req.params.id);
    if (!found) {
      res.status(404).json({ error: "not found" });
      return;
    }
    res.json(found);
  });

  return router;
}
